<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Three Biome Islands</title>
<style>
  html, body { margin: 0; padding: 0; overflow: hidden; background: #0b1a2b; }
  canvas { display: block; }
  #hud {
    position: fixed; top: 18px; left: 20px; z-index: 10;
    font-family: "Segoe UI", system-ui, sans-serif; color: #eaf3ff;
    pointer-events: none; user-select: none;
  }
  #hud h1 { margin: 0; font-size: 20px; font-weight: 700; letter-spacing: 3px; text-shadow: 0 2px 12px rgba(0,0,0,.5); }
  #hud p { margin: 4px 0 0; font-size: 12px; opacity: .7; letter-spacing: 1px; }
</style>
</head>
<body>
<div id="hud">
  <h1>MINIATURE BIOMES</h1>
  <p>desert · forest · snow — a slow orbit</p>
</div>

<script type="importmap">
{ "imports": { "three": "https://unpkg.com/three@0.160.0/build/three.module.js" } }
</script>

<script type="module">
import * as THREE from 'three';

/* ---------- helpers ---------- */
const rand = (a, b) => a + Math.random() * (b - a);
const pick = arr => arr[(Math.random() * arr.length) | 0];
const mat = (c, o = {}) => new THREE.MeshStandardMaterial(Object.assign({ color: c, roughness: 0.9, metalness: 0 }, o));

/* ---------- renderer / scene / camera ---------- */
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
document.body.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0b1a2b);
scene.fog = new THREE.Fog(0x0b1a2b, 45, 130);

const camera = new THREE.PerspectiveCamera(50, window.innerWidth / window.innerHeight, 0.1, 500);

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0xbfe3ff, 0x2a3a2a, 0.55));
const sun = new THREE.DirectionalLight(0xfff2d6, 1.35);
sun.position.set(28, 42, 18);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 140;
sun.shadow.camera.left = -45; sun.shadow.camera.right = 45;
sun.shadow.camera.top = 45; sun.shadow.camera.bottom = -45;
sun.shadow.bias = -0.0004;
scene.add(sun);

/* ---------- water ---------- */
const water = new THREE.Mesh(
  new THREE.PlaneGeometry(400, 400),
  new THREE.MeshStandardMaterial({ color: 0x123a52, roughness: 0.15, metalness: 0.35 })
);
water.rotation.x = -Math.PI / 2;
water.position.y = 0;
scene.add(water);

/* ---------- island base ---------- */
function makeIsland(radius, height, color, rough = 0.95) {
  const g = new THREE.CylinderGeometry(radius * 0.9, radius * 1.15, height, 48, 1);
  const pos = g.attributes.position;
  for (let i = 0; i < pos.count; i++) {
    const x = pos.getX(i), y = pos.getY(i), z = pos.getZ(i);
    const r = Math.hypot(x, z);
    if (r > 0.001) {
      const n = Math.sin(x * 0.9 + z * 0.7) * 0.5 + Math.cos(x * 0.5 - z * 1.1) * 0.5;
      const f = (r / radius) * (r / radius);
      pos.setX(i, x + (x / r) * n * 0.5 * f);
      pos.setZ(i, z + (z / r) * n * 0.5 * f);
    }
    if (y > 0) pos.setY(i, y + Math.sin(x * 1.3 + z * 1.1) * 0.12);
  }
  g.computeVertexNormals();
  const m = new THREE.Mesh(g, mat(color, { roughness: rough }));
  m.position.y = height / 2;
  m.castShadow = m.receiveShadow = true;
  return m;
}

/* ---------- vegetation ---------- */
function cactus() {
  const g = new THREE.Group();
  const m = mat(0x4f8a3d, { roughness: 0.8 });
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.2, 1.4, 10), m);
  body.position.y = 0.7; g.add(body);
  const arm = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.12, 0.7, 8), m);
  arm.position.set(0.32, 0.9, 0); arm.rotation.z = -0.7; g.add(arm);
  const cap = new THREE.Mesh(new THREE.SphereGeometry(0.18, 10, 8), m);
  cap.position.y = 1.4; g.add(cap);
  g.traverse(o => { if (o.isMesh) { o.castShadow = true; } });
  return g;
}
function palm() {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.2, 2.2, 8), mat(0x8a6a3a));
  trunk.position.y = 1.1; g.add(trunk);
  const leafM = mat(0x3f7d3a, { roughness: 0.85 });
  for (let i = 0; i < 6; i++) {
    const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.14, 1.4, 4), leafM);
    const a = (i / 6) * Math.PI * 2;
    leaf.position.set(Math.cos(a) * 0.5, 2.2, Math.sin(a) * 0.5);
    leaf.rotation.z = Math.cos(a) * 0.9; leaf.rotation.x = -Math.sin(a) * 0.9;
    g.add(leaf);
  }
  g.traverse(o => { if (o.isMesh) o.castShadow = true; });
  return g;
}
function pine() {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.16, 0.8, 8), mat(0x5a3a22));
  trunk.position.y = 0.4; g.add(trunk);
  const m = mat(0x2f6b3a, { roughness: 0.9 });
  const tiers = [[0.9, 1.0, 0.9], [0.7, 0.9, 1.6], [0.5, 0.8, 2.2]];
  tiers.forEach(([r, h, y]) => {
    const c = new THREE.Mesh(new THREE.ConeGeometry(r, h, 10), m);
    c.position.y = y; g.add(c);
  });
  g.traverse(o => { if (o.isMesh) o.castShadow = true; });
  return g;
}
function snowPine() {
  const g = new THREE.Group();
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.14, 0.6, 8), mat(0x4a3320));
  trunk.position.y = 0.3; g.add(trunk);
  const m = mat(0x274a3a, { roughness: 0.9 });
  const tiers = [[0.7, 0.9, 0.8], [0.55, 0.8, 1.4], [0.4, 0.7, 1.9]];
  tiers.forEach(([r, h, y]) => {
    const c = new THREE.Mesh(new THREE.ConeGeometry(r, h, 10), m);
    c.position.y = y; g.add(c);
    const snow = new THREE.Mesh(new THREE.ConeGeometry(r * 0.7, h * 0.35, 10), mat(0xf4fbff, { roughness: 0.6 }));
    snow.position.y = y + h * 0.3; g.add(snow);
  });
  g.traverse(o => { if (o.isMesh) o.castShadow = true; });
  return g;
}
function rock() {
  const m = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(0.3, 0.6), 0), mat(0x8a8f96, { roughness: 1 }));
  m.scale.set(rand(0.8, 1.3), rand(0.6, 1), rand(0.8, 1.3));
  m.castShadow = m.receiveShadow = true;
  return m;
}
function snowRock() {
  const g = new THREE.Group();
  const r = new THREE.Mesh(new THREE.DodecahedronGeometry(rand(0.35, 0.6), 0), mat(0x9aa0a8, { roughness: 1 }));
  r.scale.set(rand(0.9, 1.3), rand(0.7, 1), rand(0.9, 1.3));
  g.add(r);
