/* ---------- procedural textures (no external assets) ---------- */
function canvasTex(size, draw){
  const c = document.createElement('canvas'); c.width = c.height = size;
  draw(c.getContext('2d'), size);
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
function glowTex(){
  return canvasTex(256,(ctx,s)=>{
    const g = ctx.createRadialGradient(s/2,s/2,0,s/2,s/2,s/2);
    g.addColorStop(0,'rgba(255,255,255,1)');
    g.addColorStop(.25,'rgba(255,220,150,.55)');
    g.addColorStop(.6,'rgba(255,150,60,.12)');
    g.addColorStop(1,'rgba(255,120,40,0)');
    ctx.fillStyle=g; ctx.fillRect(0,0,s,s);
  });
}
function planetTex(base, spot, spotColor, bands){
  return canvasTex(512,(ctx,s)=>{
    ctx.fillStyle=base; ctx.fillRect(0,0,s,s);
    if(bands){
      for(let i=0;i<14;i++){
        const y=(i/14)*s, h=s/14;
        ctx.fillStyle=`rgba(${spotColor},${0.05+Math.random()*0.12})`;
        ctx.fillRect(0,y,s,h*(0.4+Math.random()*0.6));
      }
    }
    for(let i=0;i<spot;i++){
      const x=Math.random()*s, y=Math.random()*s, r=4+Math.random()*26;
      const g=ctx.createRadialGradient(x,y,0,x,y,r);
      g.addColorStop(0,`rgba(${spotColor},.5)`);
      g.addColorStop(1,`rgba(${spotColor},0)`);
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,r,0,7); ctx.fill();
