];

const orbitLines = [];
const pickables = [];
const bodies = [];

PLANETS.forEach((p,i)=>{
  const pivot = new THREE.Object3D();
  pivot.rotation.y = Math.random()*Math.PI*2;
  scene.add(pivot);

  const mesh = new THREE.Mesh(
    new THREE.SphereGeometry(p.radius, 48, 48),
    new THREE.MeshStandardMaterial({map:p.tex, roughness:0.85, metalness:0.05,
      emissive:new THREE.Color(p.color), emissiveIntensity:0.06})
  );
  mesh.position.x = p.orbit;
  mesh.rotation.z = p.tilt;
  mesh.userData = {name:p.name, type:'planet', index:i};
  pivot.add(mesh);
