  );
  scene.add(ring);
  orbitLines.push(ring);

  const body = {pivot, mesh, speed:p.speed, name:p.name, color:p.color, radius:p.radius, orbit:p.orbit};

  if(p.moon){
    const mpivot = new THREE.Object3D();
    mpivot.rotation.y = Math.random()*Math.PI*2;
    mesh.add(mpivot);
    const mmesh = new THREE.Mesh(
      new THREE.SphereGeometry(p.moon.radius, 32, 32),
      new THREE.MeshStandardMaterial({color:p.moon.color, roughness:0.95, metalness:0})
