const pos = new Float32Array(STAR_COUNT*3);
const col = new Float32Array(STAR_COUNT*3);
const palette = [new THREE.Color(0xffffff), new THREE.Color(0xbfd4ff),
                 new THREE.Color(0xffe0b0), new THREE.Color(0xffd0d0)];
for(let i=0;i<STAR_COUNT;i++){
  const r = 400 + Math.random()*900;
  const th = Math.random()*Math.PI*2;
  const ph = Math.acos(2*Math.random()-1);
  pos[i*3]   = r*Math.sin(ph)*Math.cos(th);
  pos[i*3+1] = r*Math.cos(ph);
  pos[i*3+2] = r*Math.sin(ph)*Math.sin(th);
  const c = palette[(Math.random()*palette.length)|0];
  const b = 0.5 + Math.random()*0.5;
  col[i*3]=c.r*b; col[i*3+1]=c.g*b; col[i*3+2]=c.b*b;
}
starGeo.setAttribute('position', new THREE.BufferAttribute(pos,3));
starGeo.setAttribute('color', new THREE.BufferAttribute(col,3));
const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
  size:2.4, sizeAttenuation:true, vertexColors:true, transparent:true,
  opacity:0.95, depthWrite:false, blending:THREE.AdditiveBlending
