scene.add(stars);

/* ---------- camera controls (custom orbit) ---------- */
const ctrl = {
  target:new THREE.Vector3(0,0,0),
  theta:0.6, phi:1.15, radius:132,
  tTarget:new THREE.Vector3(0,0,0),
