  const r=ctrl.radius, ph=ctrl.phi, th=ctrl.theta;
  camera.position.set(
    ctrl.target.x + r*Math.sin(ph)*Math.cos(th),
    ctrl.target.y + r*Math.cos(ph),
    ctrl.target.z + r*Math.sin(ph)*Math.sin(th)
  );
  camera.lookAt(ctrl.target);
}
