dom.addEventListener('pointerdown',e=>{ctrl.dragging=true;ctrl.px=e.clientX;ctrl.py=e.clientY;dom.setPointerCapture(e.pointerId);});
dom.addEventListener('pointermove',e=>{
  if(!ctrl.dragging) return;
  ctrl.tTheta -= (e.clientX-ctrl.px)*0.005;
  ctrl.tPhi   -= (e.clientY-ctrl.py)*0.005;
