const speedEl=document.getElementById('speed'), speedVal=document.getElementById('speedVal');
speedEl.addEventListener('input',()=>{speedMul=parseFloat(speedEl.value);speedVal.textContent=speedMul.toFixed(1)+'×';});
const orbitsBtn=document.getElementById('orbitsBtn');
orbitsBtn.addEventListener('click',()=>{
  const on=orbitsBtn.classList.toggle('on');
  orbitLines.forEach(l=>l.visible=on);
});
