/* ---------- animate ---------- */
const clock = new THREE.Clock();
function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  // orbits
  bodies.forEach(b=>{
    b.pivot.rotation.y += b.speed*speedMul*dt;
    b.mesh.rotation.y += 0.4*speedMul*dt;
    if(b.moon){
