  ctrl.phi    += (ctrl.tPhi   -ctrl.phi   )*0.08;
  ctrl.radius += (ctrl.tRadius-ctrl.radius)*0.08;
  if(focus){
    const wp = new THREE.Vector3();
    focus.mesh.getWorldPosition(wp);
    ctrl.tTarget.copy(wp);
  }
  ctrl.target.lerp(ctrl.tTarget, 0.08);
  applyCam();

  renderer.render(scene,camera);
}
animate();

/* hide loader */
setTimeout(()=>document.getElementById('loader').classList.add('hide'), 500);
