<body>
<div id="hud">
  <h1>Procedural <span>City</span> Block</h1>
  <p>30+ buildings · directional shadows · slow fly-down the main street</p>
</div>

<script type="importmap">
{ "imports": { "three": "https://unpkg.com/three@0.160.0/build/three.module.js" } }
</script>

<script type="module">
import * as THREE from 'three';

/* ---------- deterministic RNG ---------- */
function mulberry32(a){
  return function(){
    a |= 0; a = a + 0x6D2B79F5 | 0;
    let t = Math.imul(a ^ a >>> 15, 1 | a);
    t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
    return ((t ^ t >>> 14) >>> 0) / 4294967296;
  };
}
const rand = mulberry32(20240517);
const pick = arr => arr[Math.floor(rand() * arr.length)];

/* ---------- renderer ---------- */
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.outputColorSpace = THREE.SRGBColorSpace;
document.body.appendChild(renderer.domElement);

/* ---------- scene + sky ---------- */
const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0x9fb4d6, 130, 430);

const skyGeo = new THREE.SphereGeometry(1000, 32, 16);
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  uniforms: {
    topColor:    { value: new THREE.Color(0x2f5aa0) },
    midColor:    { value: new THREE.Color(0x8fb0e0) },
    bottomColor: { value: new THREE.Color(0xf3d3a6) }
  },
  vertexShader: `
    varying vec3 vPos;
    void main(){ vPos = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`,
  fragmentShader: `
    uniform vec3 topColor; uniform vec3 midColor; uniform vec3 bottomColor;
    varying vec3 vPos;
    void main(){
      float h = normalize(vPos).y;
      vec3 col = mix(bottomColor, midColor, smoothstep(-0.15, 0.12, h));
      col = mix(col, topColor, smoothstep(0.12, 0.65, h));
      gl_FragColor = vec4(col, 1.0);
    }`
});
scene.add(new THREE.Mesh(skyGeo, skyMat));

/* ---------- camera ---------- */
const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 2000);
camera.position.set(0, 12, 150);

/* ---------- lights ---------- */
scene.add(new THREE.HemisphereLight(0xbcd4ff, 0x3a3328, 0.55));

const sun = new THREE.DirectionalLight(0xffe6c0, 2.4);
sun.position.set(70, 120, 40);
sun.castShadow = true;
sun.shadow.mapSize.set(2048, 2048);
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 400;
sun.shadow.camera.left = -130;
sun.shadow.camera.right = 130;
sun.shadow.camera.top = 130;
sun.shadow.camera.bottom = -130;
sun.shadow.bias = -0.0004;
sun.shadow.normalBias = 0.02;
scene.add(sun);
scene.add(sun.target);

/* ---------- ground ---------- */
const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(600, 600),
  new THREE.MeshStandardMaterial({ color: 0x2b2f38, roughness: 1, metalness: 0 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

/* ---------- road grid ---------- */
const roadMat = new THREE.MeshStandardMaterial({ color: 0x23262d, roughness: 0.95, metalness: 0 });
const lineMat = new THREE.MeshStandardMaterial({ color: 0xd8c48a, roughness: 0.8, metalness: 0 });

const GRID = 5;          // 5x5 blocks -> 6x6 roads
const BLOCK = 26;        // block size
const ROAD  = 12;        // road width
const PITCH = BLOCK + ROAD;
const HALF  = (GRID * PITCH) / 2;

const roadGeo = new THREE.PlaneGeometry(1, 1);
roadGeo.rotateX(-Math.PI / 2);
const lineGeo = new THREE.PlaneGeometry(1, 1);
lineGeo.rotateX(-Math.PI / 2);

for (let i = 0; i <= GRID; i++){
  const c = -HALF + i * PITCH;
  const hRoad = new THREE.Mesh(roadGeo, roadMat);
  hRoad.scale.set(GRID * PITCH + ROAD, ROAD, 1);
  hRoad.position.set(0, 0.02, c);
  hRoad.receiveShadow = true;
  scene.add(hRoad);

  const vRoad = new THREE.Mesh(roadGeo, roadMat);
  vRoad.scale.set(ROAD, GRID * PITCH + ROAD, 1);
  vRoad.position.set(c, 0.02, 0);
  vRoad.receiveShadow = true;
  scene.add(vRoad);

  // dashed centre lines
  for (let d = -HALF + 3; d < HALF - 3; d += 6){
    const hl = new THREE.Mesh(lineGeo, lineMat);
    hl.scale.set(3, 0.28, 1);
    hl.position.set(d, 0.03, c);
    scene.add(hl);

    const vl = new THREE.Mesh(lineGeo, lineMat);
    vl.scale.set(0.28, 3, 1);
    vl.position.set(c, 0.03, d);
    scene.add(vl);
  }
}

/* ---------- buildings ---------- */
const boxGeo = new THREE.BoxGeometry(1, 1, 1);
boxGeo.translate(0, 0.5, 0); // pivot at base

const palette = [0x8a93a3, 0x6f7a8c, 0x9aa0a8, 0x5c6675, 0x7d8794, 0x4f5a68, 0xaab0b8, 0x6b7280];
const winOn  = [0xffd27a, 0xffe6a8, 0xffb86b, 0xffe0b0];
const winOff = [0x2a3550, 0x232c44, 0x33405e];

function makeBuilding(x, z, w, d, h){
  const g = new THREE.Group();

  const bodyMat = new THREE.MeshStandardMaterial({
    color: pick(palette), roughness: 0.85, metalness: 0.05
  });
  const body = new THREE.Mesh(boxGeo, bodyMat);
  body.scale.set(w, h, d);
  body.castShadow = true;
  body.receiveShadow = true;
  g.add(body);

  // rooftop detail
  if (rand() < 0.7){
    const cap = new THREE.Mesh(boxGeo, bodyMat);
    cap.scale.set(w * 0.5, 1.2, d * 0.5);
    cap.position.set((rand() - 0.5) * w * 0.3, h, (rand() - 0.5) * d * 0.3);
    cap.castShadow = true;
    g.add(cap);
  }
  if (rand() < 0.4){
    const ant = new THREE.Mesh(
      new THREE.CylinderGeometry(0.12, 0.12, 3 + rand() * 3, 6),
      new THREE.MeshStandardMaterial({ color: 0x333844, roughness: 0.6 })
    );
    ant.position.set(0, h + 1.5, 0);
    ant.castShadow = true;
    g.add(ant);
  }

  // emissive window strips (front + back)
  const winMat = new THREE.MeshStandardMaterial({
    color: 0x0a0d14, roughness: 0.4, metalness: 0.1,
    emissive: new THREE.Color(pick(winOn)), emissiveIntensity: 0.9
  });
  const winMat2 = new THREE.MeshStandardMaterial({
    color: 0x0a0d14, roughness: 0.4, metalness: 0.1,
    emissive: new THREE.Color(pick(winOff)), emissiveIntensity: 0.25
  });
  const floors = Math.max(2, Math.floor(h / 3));
  const stripH = 1.1;
  for (let f = 0; f < floors; f++){
    const y = 1.6 + f * 3;
    if (y > h - 1.2) break;
    const front = new THREE.Mesh(boxGeo, rand() < 0.55 ? winMat : winMat2);
    front.scale.set(w * 0.82, stripH, 0.12);
    front.position.set(0, y, d / 2 + 0.02);
    g.add(front);
    const back = new THREE.Mesh(boxGeo, rand() < 0.55 ? winMat : winMat2);
    back.scale.set(w * 0.82, stripH, 0.12);
    back.position.set(0, y, -d / 2 - 0.02);
    g.add(back);
  }

  g.position.set(x, 0, z);
  return g;
}

const buildings = [];
for (let bx = 0; bx < GRID; bx++){
  for (let bz = 0; bz < GRID; bz++){
    const cx = -HALF + ROAD / 2 + bx * PITCH + BLOCK / 2;
    const cz = -HALF + ROAD / 2 + bz * PITCH + BLOCK / 2;
    const count = 1 + Math.floor(rand() * 3); // 1..3 per block
    for (let k = 0; k < count; k++){
      const w = 6 + rand() * 8;
      const d = 6 + rand() * 8;
      const h = 8 + Math.pow(rand(), 1.6) * 46; // mostly low, some tall
      const ox = (rand() - 0.5) * (BLOCK - w - 4);
      const oz = (rand() - 0.5) * (BLOCK - d - 4);
      const b = makeBuilding(cx + ox, cz + oz, w, d, h);
      scene.add(b);
      buildings.push(b);
    }
  }
}

/* ---------- camera fly path ---------- */
const FLY_SPEED = 6;
const FLY_START = 150;
const FLY_END   = -HALF - 20;
let flyZ = FLY_START;

function animate(){
  requestAnimationFrame(animate);

  flyZ -= FLY_SPEED * 0.016;
  if (flyZ < FLY_END) flyZ = FLY_START;

  const t = performance.now() * 0.001;
  camera.position.set(Math.sin(t * 0.3) * 2.5, 12 + Math.sin(t * 0.5) * 0.6, flyZ);
  camera.lookAt(0, 8, flyZ - 25);

  // keep the shadow frustum centred on the camera
  sun.position.set(camera.position.x + 70, 120, camera.position.z + 40);
  sun.target.position.set(camera.position.x, 0, camera.position.z - 20);
  sun.target.updateMatrixWorld();

  renderer.render(scene, camera);
}
animate();

/* ---------- resize ---------- */
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

/* ---------- expose for inspection ---------- */
window.SCENE = scene;
window.CAMERA = camera;
window.RENDERER = renderer;
</script>
</body>
</html>
